// Blockchain Configuration Types
export interface Blockchain {
  id: string;
  name: string;
  symbol: string;
  chainId: number;
  type: 'evm' | 'utxo' | 'account' | 'cosmos' | 'solana' | 'aptos' | 'sui';
  rpcUrl: string;
  explorerUrl: string;
  logoUrl: string;
  isActive: boolean;
  isTestnet: boolean;
  decimals: number;
  gasToken: string;
  avgBlockTime: number;
  maxGasPrice: bigint;
  supportsEIP1559: boolean;
  contracts: TokenContract[];
}

export interface TokenContract {
  id: string;
  blockchainId: string;
  symbol: string;
  name: string;
  decimals: number;
  address: string | null; // null for native tokens
  type: 'native' | 'erc20' | 'erc721' | 'erc1155' | 'spl' | 'token' | 'evm' | 'solana' | 'aptos' | 'sui' | 'cosmos' | 'utxo';
  totalSupply: string;
  logoUrl: string;
  isActive: boolean;
  isPopular: boolean;
  priceUSD: number;
  marketCap: number;
  volume24h: number;
}

