// Blockchain and Token Management API Response Types
export interface BlockchainListResponse {
  blockchains: Blockchain[];
  total: number;
  page: number;
  limit: number;
}

export interface TokenListResponse {
  tokens: TokenContract[];
  total: number;
  page: number;
  limit: number;
}

export interface AddBlockchainRequest {
  name: string;
  symbol: string;
  chainId: number;
  type: 'evm' | 'utxo' | 'account' | 'cosmos' | 'solana' | 'aptos' | 'sui';
  rpcUrl: string;
  explorerUrl: string;
  logoUrl: string;
  decimals: number;
  gasToken: string;
  avgBlockTime: number;
  maxGasPrice: number;
  supportsEIP1559: boolean;
}

export interface AddTokenRequest {
  blockchainId: string;
  symbol: string;
  name: string;
  decimals: number;
  address: string | null;
  type: 'native' | 'erc20' | 'erc721' | 'erc1155' | 'spl' | 'token' | 'evm' | 'solana' | 'aptos' | 'sui' | 'cosmos' | 'utxo';
  totalSupply: string;
  logoUrl: string;
}

export interface UpdateBlockchainRequest extends Partial<AddBlockchainRequest> {
  isActive?: boolean;
}

export interface UpdateTokenRequest extends Partial<AddTokenRequest> {
  isActive?: boolean;
  isPopular?: boolean;
}
